import React, { useState } from 'react'
import coin_icon from 'assets/images/tu.webp'
import { useNavigate } from 'react-router-dom'
import { message, Modal } from 'antd'
import { useTranslation } from 'react-i18next'
import requestService from 'api/request'
import { useGlobalAppStore } from 'store/useGlobalApp'
import { useAuthApp } from 'store/useAuthApp'
const DailyCheckin = () => {
    const { t, i18n } = useTranslation()
    const navigate = useNavigate()
    const [openRule, setOpenRule] = useState(false)
    const { configApp } = useGlobalAppStore()
    const { user } = useAuthApp()

    const handleCheckin = async () => {
        try {
            const res = await requestService.post('/checkin')
        } catch (error: any) {
            message.error(error?.response?.data?.message)
        }
    }
    return (
        <div data-v-11ffe290="" className="mian h-screen fixed top-0 left-0  w-full">
            <Modal
                title={
                    <h4 className='text-center text-[20px]'>{t("Quy tắc nhận thưởng mỗi ngày")}</h4>
                }
                open={openRule} footer={null} onCancel={() => setOpenRule(false)} width={400} centered>

                {
                    i18n.language == 'vi' &&
                    <div data-v-2973c506="" className="con m-b-5">
                        {/* <span data-v-2973c506="" class="yuan"></span>Continuous points
                  name , without interruption;</div> */}
                        <p><strong>1. ✅ Vui lòng check-in mỗi ngày</strong> để nhận phần thưởng.<br />
                            <em>Lưu ý: Nếu bạn quên check-in hôm nay, bạn sẽ phải chờ đến tuần sau để tiếp tục check-in.</em></p>

                        <p><strong>2. 💰 Điều kiện mở tính năng check-in hằng ngày:</strong></p>
                        <ul>
                            <li>- Tài khoản của bạn phải có <strong>tổng số tiền nạp lớn hơn 10 USD</strong></li>
                            <li>- <strong>Hoặc</strong> mời đủ <strong>3 người dùng mới</strong>, và <strong>ít nhất 1 người trong số họ đã thực hiện lần nạp đầu tiên</strong></li>
                        </ul>

                        <p><strong>3. 🎁 Mẹo:</strong> Hãy thường xuyên kiểm tra và mời bạn bè để không bỏ lỡ bất kỳ phần thưởng nào nhé!</p>
                    </div>
                }
                {
                    i18n.language == 'zh' &&
                    <div data-v-2973c506="" className="con m-b-5">
                        {/* <span data-v-2973c506="" class="yuan"></span>Continuous points
    name , without interruption;</div> */}

                        <p><strong>1. ✅ 请每天签到</strong> 以领取奖励。<br />
                            <em>注意：如果今天忘记签到，您需要等到下周才能继续签到。</em></p>

                        <p><strong>2. 💰 开启每日签到功能的条件：</strong></p>
                        <ul>
                            <li>- 您的账户总充值金额需<strong>大于 10 美元</strong></li>
                            <li>- <strong>或</strong>成功邀请<strong>3 位新用户</strong>，其中<strong>至少 1 人完成首次充值</strong></li>
                        </ul>

                        <p><strong>3. 🎁 小贴士：</strong> 请经常检查并邀请好友，以免错过任何奖励！</p>
